export function wordHit(word, q) {
  if (!q) return true;
  const en = word[0].toLowerCase();
  if (en.includes(q)) return true;
  if (q.length < 2) return false;
  if (word[2].toLowerCase().includes(q)) return true;
  if (q.length < 3) return false;
  return word[1].toLowerCase().includes(q);
}
